// lib/game/audio.dart
// Music + sound effects. All files in assets/audio/ are generated by
// tools/make_audio.py (original chiptune audio).
//
// Performance notes (Android):
// * Every effect is loaded ONCE at start-up into a few low-latency players
//   (they share one SoundPool). Playing a sound just restarts one of them —
//   no players are created during gameplay, so nothing leaks and the audio
//   system never runs out of resources.
// * Each effect is rate-limited so a combo hitting 4 monsters in one frame
//   doesn't fire 4 identical sounds.
// * A watchdog restarts the background music if the system ever stops it.

import 'dart:async';
import 'dart:io' show Platform;

import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';

class GameAudio {
  GameAudio._();
  static final instance = GameAudio._();

  /// No audio device under `flutter test`; everything becomes a no-op.
  static bool disabled = !kIsWeb && Platform.environment.containsKey('FLUTTER_TEST');

  static const musicVolume = 0.45;

  /// Effects: (relative volume, players, minimum gap between plays in ms).
  /// Square waves are harsh, so those are quieter.
  static const _sfx = <String, (double, int, int)>{
    'swing': (0.55, 3, 60),
    'hit': (0.7, 3, 55),
    'hit_heavy': (0.9, 1, 120),
    'hurt': (0.5, 1, 150),
    'jump': (0.3, 2, 80),
    'roll': (0.5, 1, 120),
    'power': (0.6, 1, 300),
    'magic': (0.45, 3, 60),
    'pickup': (0.4, 2, 80),
    'block': (0.5, 2, 80),
    'poof': (0.6, 2, 90),
    'cast': (0.4, 1, 250),
    'quake': (0.8, 1, 300),
    'perfect': (0.6, 1, 300),
    'perk': (0.6, 1, 300),
    'wave': (0.45, 1, 400),
    'click': (0.4, 2, 60),
    'door': (0.5, 1, 400),
    'midterm': (0.55, 1, 500),
    'victory': (0.55, 1, 500),
    'graduate': (0.6, 1, 500),
    'gameover': (0.6, 1, 500),
    'laugh': (0.85, 1, 1200),
    'thunder': (0.8, 1, 1200),
    'heartbeat': (0.7, 1, 600),
  };

  bool musicOn = true;
  bool sfxOn = true;

  bool _ready = false;
  final _voices = <String, List<AudioPlayer>>{};
  final _next = <String, int>{};
  final _lastPlay = <String, int>{};
  final _clock = Stopwatch()..start();

  String? _track; // track that should be playing
  String? _playing; // track we last started
  bool _ducked = false;
  int _lastMusicCheck = 0;
  Future<void> _musicOps = Future.value();

  Future<void> init() async {
    if (disabled || _ready) return;
    try {
      // Game sounds must not grab Android "audio focus": otherwise every effect
      // tells the previous one (and the music) to pause, and they cut each other off.
      final mix = AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build();
      await AudioPlayer.global.setAudioContext(mix);
      await FlameAudio.bgm.initialize(audioContext: mix); // auto-pauses music when the app is backgrounded
      for (final e in _sfx.entries) {
        final (volume, count, _) = e.value;
        final players = <AudioPlayer>[];
        for (var i = 0; i < count; i++) {
          final p = AudioPlayer()..audioCache = FlameAudio.audioCache;
          await p.setAudioContext(mix);
          await p.setPlayerMode(PlayerMode.lowLatency);
          await p.setReleaseMode(ReleaseMode.stop);
          await p.setVolume(volume);
          await p.setSource(AssetSource('${e.key}.wav'));
          players.add(p);
        }
        _voices[e.key] = players;
      }
      _ready = true;
      _applyMusic();
    } catch (e) {
      debugPrint('Audio unavailable: $e');
    }
  }

  /// Plays a sound effect. Cheap and safe to call every frame.
  void play(String name) {
    if (!_ready || !sfxOn) return;
    final players = _voices[name];
    final spec = _sfx[name];
    if (players == null || spec == null) return;
    final now = _clock.elapsedMilliseconds;
    if (now - (_lastPlay[name] ?? -100000) < spec.$3) return;
    _lastPlay[name] = now;
    final i = (_next[name] ?? 0) % players.length;
    _next[name] = i + 1;
    unawaited(_restart(players[i]));
  }

  Future<void> _restart(AudioPlayer p) async {
    try {
      await p.stop(); // a finished low-latency stream must be stopped before it can replay
      await p.resume();
    } catch (_) {}
  }

  /// Switches the background track (no-op if it's already playing).
  /// Called every frame, so it also checks now and then that the music
  /// is really still playing.
  void music(String? track) {
    if (track != _track) {
      _track = track;
      _applyMusic();
      return;
    }
    final now = _clock.elapsedMilliseconds;
    if (!_ready || now - _lastMusicCheck < 3000) return;
    _lastMusicCheck = now;
    final state = FlameAudio.bgm.audioPlayer.state;
    if (_playing != null && (state == PlayerState.stopped || state == PlayerState.completed)) {
      _playing = null; // the system stopped it; start it again
      _applyMusic();
    }
  }

  /// Quieter music while paused.
  void duck(bool on) {
    if (_ducked == on) return;
    _ducked = on;
    _queue(() async {
      if (_playing != null) await FlameAudio.bgm.audioPlayer.setVolume(_volume);
    });
  }

  double get _volume => _ducked ? musicVolume * 0.3 : musicVolume;

  void setMusic(bool on) {
    musicOn = on;
    _applyMusic();
  }

  void setSfx(bool on) => sfxOn = on;

  void _applyMusic() {
    if (!_ready) return;
    final want = musicOn ? _track : null;
    if (want == _playing) return;
    _playing = want;
    _queue(() async {
      try {
        if (want == null) {
          await FlameAudio.bgm.stop();
        } else {
          await FlameAudio.bgm.play('$want.wav', volume: _volume);
        }
      } catch (e) {
        debugPrint('Music error: $e');
        if (_playing == want) _playing = null; // let the next check retry
      }
    });
  }

  /// Runs music operations one at a time so quick track changes don't overlap.
  void _queue(Future<void> Function() op) {
    _musicOps = _musicOps.then((_) => op()).then((_) {}, onError: (Object e) => debugPrint('Music error: $e'));
  }
}
